command:
// Rolls the Queen's Tempest hazard routine (1d3) and whispers the result to the GMs.
// A destroyed anchor produces nothing and is never rerolled, so the macro checks each
// Tempest's HP first. The actor ids survive the Adventure import (keepId).
const ANCHORS = [
  {
    id: 'TempestVortxMTah',
    name: 'Vortex Tempest',
    effect: 'Thunderclap',
    detail: '60-foot burst in the selected sector. DC 38 Fortitude, 8d10 sonic on a failure.',
  },
  {
    id: 'TempestLghtnPWdk',
    name: 'Lightning Tempest',
    effect: "Queen's Lightning",
    detail: '1 creature in the selected sector. DC 38 Reflex, 10d8 electricity on a failure.',
  },
  {
    id: 'TempestDelugZgnu',
    name: 'Deluge Tempest',
    effect: 'Rending Deluge',
    detail: '30-foot cone from an edge or watercourse. DC 38 Reflex, 6d10 bludgeoning on a failure.',
  },
];

const roll = await new Roll('1d3').evaluate();
const anchor = ANCHORS[roll.total - 1];
const actor = game.actors.get(anchor.id);
const destroyed = (actor?.system?.attributes?.hp?.value ?? 1) <= 0;

const body = destroyed
  ? `<p><strong>${anchor.name}</strong> is destroyed. The clouds strain toward
     ${anchor.effect} and falter &mdash; the storm takes no action this round.</p>
     <p><em>Do not reroll.</em></p>`
  : `<p><strong>${anchor.effect}</strong> &mdash; ${anchor.name}</p>
     <p>${anchor.detail}</p>
     <p>Roll a random painted cell, resolve the effect there, then place the collateral
     marker and name what is about to be lost.</p>`;

await ChatMessage.create({
  speaker: { alias: "Queen's Tempest" },
  flavor: 'Hazard routine',
  rolls: [roll],
  content: (await roll.render()) + body,
  whisper: game.users.filter((u) => u.isGM).map((u) => u.id),
});
